import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { DashboardService } from '../../services/dashboard.service';
import { ExportService } from '../../services/export.service';

interface DashboardResumo {
  saldo_atual: number;
  receitas: number;
  despesas: number;
  total_transacoes?: number;
}

interface Cotacoes {
  USD_BRL?: { cotacao: number; baixa?: number; alta?: number };
  EUR_BRL?: { cotacao: number; baixa?: number; alta?: number };
}

interface DashboardData {
  resumo: DashboardResumo;
  cotacoes_atuais: Cotacoes;
  data_atualizacao: string;
}

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit {
  isLoading = true;
  hasError = false;
  errorMessage = '';
  isExporting = false;

  resumo: DashboardResumo | null = null;
  cotacoes: Cotacoes | null = null;
  dataAtualizacao: string | null = null;

  // Valores convertidos
  saldoEmUSD = 0;
  saldoEmEUR = 0;
  receitasEmUSD = 0;
  despesasEmUSD = 0;

  constructor(
    private dashboardService: DashboardService,
    private exportService: ExportService
  ) { }

  ngOnInit(): void {
    this.carregarDados();
  }

  private carregarDados(): void {
    this.isLoading = true;
    this.hasError = false;

    this.dashboardService.obterResumo().subscribe({
      next: (response: any) => {
        if (response && response.data) {
          this.resumo = response.data;
          this.cotacoes = response.data.cotacoes || {};
          this.dataAtualizacao = new Date().toLocaleString('pt-BR');
          this.calcularConversoes();
        }
        this.isLoading = false;
      },
      error: (error: any) => {
        console.error('Erro ao carregar dashboard:', error);
        this.hasError = true;
        this.errorMessage = 'Erro ao carregar dados do dashboard. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  private calcularConversoes(): void {
    if (!this.resumo || !this.cotacoes) return;

    const cotacaoUSD = this.cotacoes.USD_BRL?.cotacao || 0;
    const cotacaoEUR = this.cotacoes.EUR_BRL?.cotacao || 0;

    if (cotacaoUSD > 0) {
      this.saldoEmUSD = this.resumo.saldo_atual / cotacaoUSD;
      this.receitasEmUSD = this.resumo.receitas / cotacaoUSD;
      this.despesasEmUSD = this.resumo.despesas / cotacaoUSD;
    }

    if (cotacaoEUR > 0) {
      this.saldoEmEUR = this.resumo.saldo_atual / cotacaoEUR;
    }
  }

  recarregar(): void {
    this.carregarDados();
  }

  /**
   * Inicia o download do relatório CSV
   */
  exportarCsv(): void {
    this.isExporting = true;
    this.hasError = false;

    try {
      this.exportService.exportarCsv('relatorio_financeiro.csv');
      this.isExporting = false;
    } catch (error: any) {
      console.error('Erro ao exportar:', error);
      this.hasError = true;
      this.errorMessage = error.message || 'Erro ao exportar o relatório. Tente novamente.';
      this.isExporting = false;
    }
  }

  formatarMoeda(valor: number, moeda: string = 'BRL'): string {
    const locale = 'pt-BR';
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: moeda
    }).format(valor);
  }
}
<div class="dashboard-container">
  <div class="dashboard-shell">
    <section class="dashboard-intro">
      <h2>Resumo Financeiro</h2>
      <p>Uma visão rápida e elegante da sua saúde financeira.</p>
    </section>

    <div *ngIf="isLoading" class="loading-state">
      <div class="spinner"></div>
      <p>Carregando dados...</p>
    </div>

    <div *ngIf="hasError && !isLoading" class="error-state">
      <div class="error-icon">⚠️</div>
      <h3>Erro ao carregar</h3>
      <p>{{ errorMessage }}</p>
      <button class="btn-retry" (click)="recarregar()">Tentar novamente</button>
    </div>

    <div *ngIf="!isLoading && !hasError && resumo" class="dashboard-content">
      <section class="summary-grid">
        <article class="summary-card card-saldo">
          <header>
            <span>Saldo Atual</span>
            <small>{{ dataAtualizacao }}</small>
          </header>
          <div class="saldo-value">{{ formatarMoeda(resumo.saldo_atual) }}</div>
          <footer>
            <span *ngIf="resumo.saldo_atual >= 0">Situação positiva</span>
            <span *ngIf="resumo.saldo_atual < 0">Atenção ao fluxo de caixa</span>
          </footer>
        </article>

        <article class="summary-card card-receitas">
          <header>
            <span>Receitas</span>
            <strong>↗</strong>
          </header>
          <div class="money positive">{{ formatarMoeda(resumo.receitas) }}</div>
          <p>Total de entradas no período</p>
        </article>

        <article class="summary-card card-despesas">
          <header>
            <span>Despesas</span>
            <strong>↘</strong>
          </header>
          <div class="money negative">{{ formatarMoeda(resumo.despesas) }}</div>
          <p>Total de saídas no período</p>
        </article>
      </section>

      <section class="widget-grid">
        <article class="widget-card cambio" *ngIf="cotacoes">
          <div class="widget-head">
            <h3>Câmbio Atual</h3>
            <span>Atualizado</span>
          </div>

          <div class="cambio-list" *ngIf="cotacoes.USD_BRL || cotacoes.EUR_BRL">
            <div *ngIf="cotacoes.USD_BRL" class="cambio-item">
              <span>USD/BRL</span>
              <strong>{{ cotacoes.USD_BRL.cotacao | number:'1.2-2' }}</strong>
            </div>
            <div *ngIf="cotacoes.EUR_BRL" class="cambio-item">
              <span>EUR/BRL</span>
              <strong>{{ cotacoes.EUR_BRL.cotacao | number:'1.2-2' }}</strong>
            </div>
          </div>
        </article>

        <article class="widget-card actions">
          <div class="widget-head">
            <h3>Ações Rápidas</h3>
            <span>Produtividade</span>
          </div>
          <div class="actions-row">
            <button class="action-btn primary" (click)="exportarCsv()" [disabled]="isExporting">
              <span *ngIf="!isExporting">Exportar CSV</span>
              <span *ngIf="isExporting">Exportando...</span>
            </button>
            <button class="action-btn" (click)="recarregar()">Atualizar dados</button>
            <a routerLink="/transacoes" class="action-btn ghost">Ver transações</a>
          </div>
        </article>
      </section>

      <section class="recent-section">
        <div class="recent-head">
          <h3>Transações Recentes</h3>
          <a routerLink="/transacoes">Ver todas</a>
        </div>

        <div class="recent-list" *ngIf="(resumo.total_transacoes || 0) > 0; else emptyRecent">
          <article class="recent-item" *ngFor="let item of [1, 2, 3, 4, 5]">
            <div class="recent-icon">💳</div>
            <div class="recent-info">
              <strong>Movimentação #{{ item }}</strong>
              <span>Consulte o detalhe completo na área de transações</span>
            </div>
            <div class="recent-value" [class.positive]="item % 2 === 0" [class.negative]="item % 2 !== 0">
              {{ item % 2 === 0 ? '+' : '-' }} {{ formatarMoeda((resumo.saldo_atual / 20) * item) }}
            </div>
          </article>
        </div>

        <ng-template #emptyRecent>
          <div class="recent-empty">
            <p>Nenhuma transação recente para mostrar.</p>
            <a routerLink="/transacoes">Adicionar primeira transação</a>
          </div>
        </ng-template>
      </section>
    </div>
  </div>
</div>
